package app.dayflow;
import android.widget.*;
import com.google.android.material.textfield.TextInputEditText;
import org.json.*;
import java.time.*;
import java.util.*;
import java.nio.charset.StandardCharsets;

/** One independent, stable-ID note per project/day keeps sync history bounded per record. */
final class CheckIns {
 static String id(String project,LocalDate date){return UUID.nameUUIDFromBytes(("dayflow:checkin:"+project+":"+date).getBytes(StandardCharsets.UTF_8)).toString();}
 static void list(MainActivity a){LinearLayout page=a.fullPage("长期任务打卡",a::home);page.addView(Ui.text(a,"长期任务",24,true));page.addView(Ui.button(a,"＋ 新建长期任务",true,()->a.newRecord("project")));try{JSONArray projects=Data.get(a).list("project",200);for(int i=0;i<projects.length();i++){JSONObject r=projects.getJSONObject(i);page.addView(Ui.button(a,r.optString("title"),false,()->a.detail(r)));}if(projects.length()==0)page.addView(Ui.help(a,"建立学习、锻炼或种植项目，再为项目开启每日打卡。"));}catch(Exception e){a.message(e.getMessage());}}
 static void panel(MainActivity a,LinearLayout page,JSONObject project){try{String pid=project.getString("id");int[] stats=Data.get(a).checkinStats(pid);page.addView(Ui.text(a,"打卡 "+stats[0]+" 天 · 连续 "+stats[1]+" 天",19,true));int goal=project.optInt("checkin_goal",30);ProgressBar progress=new ProgressBar(a,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(Math.max(1,goal));progress.setProgress(Math.min(goal,stats[0]));page.addView(progress,new LinearLayout.LayoutParams(-1,Ui.dp(a,6)));JSONObject today=Data.get(a).find(id(pid,LocalDate.now()));boolean checked=today!=null&&!today.optBoolean("deleted");page.addView(Ui.button(a,checked?"今天已打卡 · 查看 / 撤销":"今日打卡",true,()->edit(a,project,LocalDate.now())));page.addView(Ui.button(a,"打卡记录与目标",false,()->history(a,project,0)));}catch(Exception e){a.message(e.getMessage());}}
 private static void edit(MainActivity a,JSONObject project,LocalDate date){LinearLayout page=a.fullPage("项目打卡",()->a.detail(project));page.addView(Ui.text(a,project.optString("title")+" · "+date,21,true));JSONObject existing;try{existing=Data.get(a).find(id(project.optString("id"),date));}catch(Exception e){a.message(e.getMessage());return;}TextInputEditText text=Ui.field(a,page,"今天做了什么（选填）",existing==null?"":existing.optString("content"),true);page.addView(Ui.button(a,"保存打卡",true,()->{try{JSONObject parent=Data.get(a).find(project.getString("id"));if(parent==null||parent.optBoolean("deleted"))throw new Exception("项目已被删除，请刷新");JSONObject latest=Data.get(a).find(id(project.optString("id"),date));JSONObject r=latest==null?Data.make("note",project.optString("title")+" · "+date+" 打卡"):latest;r.put("id",id(project.optString("id"),date)).put("parent_id",project.getString("id")).put("checkin_for",project.getString("id")).put("checkin_date",date.toString()).put("content",text.getText().toString()).put("content_format","markdown").put("deleted",false);Data.validate(r);Data.get(a).save(r);a.changed();a.detail(project);}catch(Exception e){a.message(e.getMessage());}}));if(existing!=null&&!existing.optBoolean("deleted"))page.addView(Ui.button(a,"撤销这一天的打卡",false,()->{try{JSONObject current=Data.get(a).find(id(project.optString("id"),date));if(current!=null)Data.get(a).save(current.put("deleted",true));a.changed();a.detail(project);}catch(Exception e){a.message(e.getMessage());}}));}
 private static void history(MainActivity a,JSONObject project,int offset){LinearLayout page=a.fullPage("打卡历史",()->a.detail(project));TextInputEditText target=Ui.field(a,page,"目标打卡天数（1–3650）",Integer.toString(project.optInt("checkin_goal",30)),false);target.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);page.addView(Ui.button(a,"保存目标",false,()->{try{int count=Integer.parseInt(target.getText().toString());if(count<1||count>3650)throw new Exception("目标需在1–3650天之间");JSONObject current=Data.get(a).find(project.getString("id"));if(current==null)throw new Exception("项目已不存在");Data.get(a).save(current.put("checkin_goal",count));a.changed();a.detail(current);}catch(Exception e){a.message(e.getMessage());}}));page.addView(Ui.button(a,"选择过去日期补卡",false,()->MonthBrowser.select(a,LocalDate.now(),date->{if(date.isAfter(LocalDate.now()))a.message("不能提前为未来日期打卡");else edit(a,project,date);},()->history(a,project,offset),false)));try{JSONArray rows=Data.get(a).checkinRows(project.getString("id"),offset);for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);page.addView(Ui.button(a,r.optString("checkin_date")+" · "+r.optString("content",""),false,()->edit(a,project,LocalDate.parse(r.optString("checkin_date")))));}if(offset>0)page.addView(Ui.button(a,"上一页",false,()->history(a,project,Math.max(0,offset-40))));if(rows.length()==40)page.addView(Ui.button(a,"下一页",false,()->history(a,project,offset+40)));}catch(Exception e){a.message(e.getMessage());}}
}
